_PERIODIC_UPPER = {k.upper(): k for k in PERIODIC_TABLE.keys()}


def canonical_element_symbol(symbol):
    """Return PERIODIC_TABLE-style element symbol (e.g. Cu, Mg, Li)."""
    if symbol is None:
        return ''
    s = str(symbol).strip()
    if not s:
        return ''
    canon = _PERIODIC_UPPER.get(s.upper())
    if canon:
        return canon
    return s[0].upper() + s[1:].lower() if len(s) > 1 else s.upper()


def format_w_element_label(element, suffix=''):
    """Display label for weight fraction axis, e.g. w(Cu) or w(Cu) (%)."""
    return f"w({canonical_element_symbol(element)}){suffix}"


def w_column_name(element, phase=None):
    """Canonical w(*) column name for DataFrames."""
    el = canonical_element_symbol(element)
    if phase:
        return f"w({el}@{phase})"
    return f"w({el})"


def format_chemistry_axis_label(label):
    """Format column/axis text so element symbols use canonical casing."""
    if not isinstance(label, str):
        return label
    s = label.strip()
    m = re.match(r'^(w)\(([^)]+)\)(.*)$', s, re.IGNORECASE)
    if m:
        inner, suffix = m.group(2), m.group(3)
        if '@' in inner:
            el, phase = inner.split('@', 1)
            return f"w({canonical_element_symbol(el)}@{phase}){suffix}"
        return f"w({canonical_element_symbol(inner)}){suffix}"
    m = re.match(r'^(1/)?(dwdT_L)\(([^)]+)\)(.*)$', s, re.IGNORECASE)
    if m:
        inv_prefix, inner, suffix = (m.group(1) or ''), m.group(3), m.group(4)
        if '@' in inner:
            el, phase = inner.split('@', 1)
            return f"{inv_prefix}dwdT_L({canonical_element_symbol(el)}@{phase}){suffix}"
        return f"{inv_prefix}dwdT_L({canonical_element_symbol(inner)}){suffix}"
    m = re.match(
        r'^(MOLE_PERCENT|ATOMIC_PERCENT|MASS_PERCENT|WEIGHT_PERCENT)_([A-Za-z0-9]+)(.*)$',
        s, re.IGNORECASE,
    )
    if m:
        prefix, el, suffix = m.group(1).upper(), m.group(2), m.group(3)
        return f"{prefix}_{canonical_element_symbol(el)}{suffix}"
    if re.fullmatch(r'[A-Za-z]{1,3}', s):
        return canonical_element_symbol(s)
    return s


def _resolve_plot_label(custom, default):
    """Use custom label when non-empty; otherwise keep the computed default."""
    if custom is None:
        return default
    s = str(custom).strip()
    return s if s else default


def standardize_dataframe_element_columns(df):
    """Rename w(*)/dwdT_L(*) columns to canonical element symbol casing."""
    if df is None or getattr(df, 'empty', True):
        return df
    mapping = {}
    for col in df.columns:
        new_col = format_chemistry_axis_label(col)
        if new_col != col:
            mapping[col] = new_col
    if mapping:
        df = df.rename(columns=mapping)
    return df

# Longest symbol first (e.g. match "Cl" before "C") when tokenizing concatenated element runs.
_PBFX_ELEM_SYMS_BY_LEN = sorted(PERIODIC_TABLE.keys(), key=lambda s: (-len(s), s))


def _pbfx_canonicalize_element_run(run):
    """
    Parse a concatenation of element symbols (any case) into canonical PERIODIC_TABLE casing.
    Returns None if the whole string cannot be split into valid symbols.
    """
    if not run:
        return ''
    lo = run.lower()
    i = 0
    parts = []
    while i < len(lo):
        matched = None
        for sym in _PBFX_ELEM_SYMS_BY_LEN:
            if lo.startswith(sym.lower(), i):
                matched = sym
                break
        if matched is None:
            return None
        parts.append(matched)
        i += len(matched)
    return ''.join(parts)


def _pbfx_canonicalize_trailing_element_run(stem):
    """If stem ends with a letter run that fully tokenizes as elements, rewrite that run with canonical casing."""
    m = re.search(r'([A-Za-z]+)$', stem)
    if not m:
        return stem
    run = m.group(1)
    canon = _pbfx_canonicalize_element_run(run)
    if canon is None:
        return stem
    return stem[: m.start(1)] + canon


def _step_to_output_decimals(step):
    """Decimal places needed so batch file values reflect the chosen step (e.g. 0.005 -> 3)."""
    try:
        d = Decimal(str(float(step))).normalize()
        if d == 0:
            return 8
        e = d.as_tuple().exponent
        return max(0, -e) if e < 0 else 0
    except Exception:
        return 8


def _composition_range_float64(lo, hi, step):
    """Inclusive lo..hi in float64 steps (avoids float32 / arange endpoint bugs)."""
    lo, hi, step = float(lo), float(hi), float(step)
    if step <= 0:
        return np.array([lo], dtype=np.float64)
    out = []
    i = 0
    while True:
        x = lo + i * step
        if x > hi + 1e-12:
            break
        out.append(x)
        i += 1
        if i > 10_000_000:
            break
    return np.array(out, dtype=np.float64)


def _lmg_normalize_axis_label(text):
    """'MOLE_PERCENT CU' -> 'MOLE_PERCENT_CU' for Excel column names."""
    return re.sub(r'\s+', '_', (text or '').strip().upper())


def _lmg_parse_temperature_from_filename(file_name):
    """Parse temperature (K) from names like AlCuLi_800.exp or AlCuLi_300K.exp."""
    base = os.path.splitext(os.path.basename(file_name))[0]
    m = re.search(r'(?:^|[_-])(\d+(?:\.\d+)?)\s*K?\s*$', base, flags=re.IGNORECASE)
    if m:
        return float(m.group(1))
    nums = re.findall(r'\d+(?:\.\d+)?', base)
    if nums:
        return float(nums[-1])
    return None


def _lmg_parse_axis_labels_from_lines(lines, max_header=40):
    x_label = y_label = None
    for line in lines[:max_header]:
        s = line.strip()
        mx = re.match(r'^XTEXT\s+(.+)$', s, flags=re.IGNORECASE)
        if mx:
            x_label = _lmg_normalize_axis_label(mx.group(1))
        my = re.match(r'^YTEXT\s+(.+)$', s, flags=re.IGNORECASE)
        if my:
            y_label = _lmg_normalize_axis_label(my.group(1))
    return x_label, y_label


def _lmg_extract_boundary_points_from_exp(file_path):
    """
    Extract miscibility gap boundary points from a Thermo-calc .exp file.
    Returns (x_col, y_col, rows) where rows is list of dicts with x, y, block, phase_hint.
    """
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except OSError:
        return None, None, []

    x_col, y_col = _lmg_parse_axis_labels_from_lines(lines)
    if not x_col or not y_col:
        return None, None, []

    rows = []
    collecting = False
    block_idx = 0
    phase_hint = ''
    for line in lines:
        s = line.strip()
        if s.startswith('$ PLOTTED'):
            collecting = True
            block_idx += 1
            phase_hint = ''
            # X(LIQUID#1,CU) -> phase name LIQUID#1 (drop component suffix after comma)
            m_ph = re.search(r'X\(([^),]+)', s, flags=re.IGNORECASE)
            if m_ph:
                phase_hint = m_ph.group(1).strip()
            continue
        if collecting and s.startswith('BLOCKEND'):
            collecting = False
            continue
        if collecting:
            parts = s.split()
            if len(parts) >= 2:
                try:
                    rows.append({
                        'x': float(parts[0]),
                        'y': float(parts[1]),
                        'block': block_idx,
                        'phase_hint': phase_hint,
                    })
                except ValueError:
                    continue
    return x_col, y_col, rows


# Default filename filters for Extract Thermo-calc Results tabs
EXPTC_MR_FILTER_DEFAULT = r'.*_np-T\.exp$'
EXPTC_LMG_FILTER_DEFAULT = r'(?i)^.+\d+(?:K)?\.exp$'

_LMG_META_COLS = frozenset({
    'File', 'Temperature_K', 'Block', 'Phase', 'Temperature', 'TEMPERATURE_K',
})


def _lmg_detect_xy_columns(df):
    """Pick X/Y composition columns from Miscibility Gap Excel."""
    cols = [c for c in df.columns if isinstance(c, str)]
    mole = [c for c in cols if c.upper().startswith('MOLE_PERCENT_')]
    if len(mole) >= 2:
        return mole[0], mole[1]
    for prefix in ('ATOMIC_PERCENT_', 'MASS_PERCENT_', 'WEIGHT_PERCENT_'):
        found = [c for c in cols if c.upper().startswith(prefix)]
        if len(found) >= 2:
            return found[0], found[1]
    numeric = []
    for c in df.columns:
        if c in _LMG_META_COLS or not isinstance(c, str):
            continue
        try:
            s = pd.to_numeric(df[c], errors='coerce')
            if s.notna().sum() >= 3:
                numeric.append(c)
        except Exception:
            continue
    if len(numeric) >= 2:
        return numeric[0], numeric[1]
    return None, None


def _lmg_resample_curve_by_arclength(x, y, n_pts):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    n_pts = max(int(n_pts), 2)
    if len(x) < 2:
        return x, y
    dx = np.diff(x)
    dy = np.diff(y)
    seg = np.hypot(dx, dy)
    s = np.concatenate([[0.0], np.cumsum(seg)])
    if s[-1] <= 0:
        t = np.linspace(0.0, 1.0, n_pts)
        return np.interp(t, [0.0, 1.0], [x[0], x[-1]]), np.interp(t, [0.0, 1.0], [y[0], y[-1]])
    s_new = np.linspace(0.0, s[-1], n_pts)
    return np.interp(s_new, s, x), np.interp(s_new, s, y)


def _lmg_ordered_group_points(gdf, x_col, y_col):
    gdf = gdf.sort_index()
    x = pd.to_numeric(gdf[x_col], errors='coerce').to_numpy(dtype=float)
    y = pd.to_numeric(gdf[y_col], errors='coerce').to_numpy(dtype=float)
    m = np.isfinite(x) & np.isfinite(y)
    return x[m], y[m]


def _lmg_split_polylines(x, y, gap_thresh=None):
    """Split ordered (x, y) into separate polylines when consecutive points are far apart."""
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if len(x) < 2:
        return [(x, y)] if len(x) else []
    if gap_thresh is None:
        span = max(float(np.ptp(x)), float(np.ptp(y)), 1e-6)
        gap_thresh = 0.05 * span
    segments = []
    start = 0
    for i in range(1, len(x)):
        if np.hypot(x[i] - x[i - 1], y[i] - y[i - 1]) > gap_thresh:
            if i - start >= 2:
                segments.append((x[start:i], y[start:i]))
            start = i
    if len(x) - start >= 2:
        segments.append((x[start:], y[start:]))
    return segments


def _lmg_phase_color_map(labels):
    """Stable phase -> color mapping for plotting (tab10 cycle)."""
    if not MATPLOTLIB_AVAILABLE:
        return {lb: None for lb in labels}
    tab10 = matplotlib.colormaps['tab10']
    unique = list(dict.fromkeys(labels))
    return {ph: tab10((i % 10) / 9.0) for i, ph in enumerate(unique)}


def _lmg_bracket_temperature(temps, t_target):
    temps = np.asarray(sorted({float(t) for t in temps if pd.notna(t)}), dtype=float)
    t_target = float(t_target)
    if len(temps) == 0:
        return None, None, 0.0
    if np.any(np.isclose(temps, t_target, rtol=0.0, atol=1e-6)):
        t_exact = float(temps[np.isclose(temps, t_target, rtol=0.0, atol=1e-6)][0])
        return t_exact, t_exact, 0.0
    if t_target <= temps[0]:
        return float(temps[0]), float(temps[0]), 0.0
    if t_target >= temps[-1]:
        return float(temps[-1]), float(temps[-1]), 0.0
    hi = int(np.searchsorted(temps, t_target, side='right'))
    t_lo, t_hi = float(temps[hi - 1]), float(temps[hi])
    alpha = (t_target - t_lo) / (t_hi - t_lo) if t_hi != t_lo else 0.0
    return t_lo, t_hi, float(alpha)


def _lmg_group_columns(df):
    cols = ['Phase']
    if 'Block' in df.columns:
        cols.append('Block')
    return cols


def _lmg_segments_for_phase_at(df, t_val, phase, x_col, y_col):
    m = np.isclose(df['Temperature_K'].astype(float), float(t_val), rtol=0.0, atol=1e-6)
    g = df.loc[m & (df['Phase'].astype(str) == str(phase))].sort_index()
    x, y = _lmg_ordered_group_points(g, x_col, y_col)
    return _lmg_split_polylines(x, y)


def _lmg_curves_at_temperature(df, t_target, x_col, y_col, n_resample=80):
    """Build boundary polylines at t_target (interpolate between bracketing temperatures if needed)."""
    curves = []
    if 'Temperature_K' not in df.columns:
        return curves, None, None, ''
    temps = df['Temperature_K'].dropna().unique()
    t_lo, t_hi, alpha = _lmg_bracket_temperature(temps, t_target)
    if t_lo is None:
        return curves, None, None, ''

    note = ''
    exact = np.any(np.isclose(temps.astype(float), float(t_target), rtol=0.0, atol=1e-6))
    if not exact and t_lo != t_hi:
        note = f'T={t_target:g} K interpolated between {t_lo:g} K and {t_hi:g} K'
    elif not exact:
        note = f'T={t_target:g} K (nearest available {t_lo:g} K)'

    n_resample = max(int(n_resample), 8)

    def _append_curve(phase, x, y):
        if len(x) < 2:
            return
        curves.append({
            'phase': str(phase),
            'x': x,
            'y': y,
            'label': str(phase),
        })

    def _interp_segment(x_lo, y_lo, x_hi, y_hi):
        if len(x_lo) < 2:
            return x_hi, y_hi
        if len(x_hi) < 2:
            return x_lo, y_lo
        x_lo, y_lo = _lmg_resample_curve_by_arclength(x_lo, y_lo, n_resample)
        x_hi, y_hi = _lmg_resample_curve_by_arclength(x_hi, y_hi, n_resample)
        return (1.0 - alpha) * x_lo + alpha * x_hi, (1.0 - alpha) * y_lo + alpha * y_hi

    if 'Block' in df.columns and 'Phase' in df.columns:
        gb_cols = _lmg_group_columns(df)

        def _subset_at(t_val, key):
            m = np.isclose(df['Temperature_K'].astype(float), float(t_val), rtol=0.0, atol=1e-6)
            g = df.loc[m]
            if not len(g):
                return g
            if isinstance(key, tuple):
                for col, val in zip(gb_cols, key):
                    g = g[g[col] == val]
            else:
                g = g[g['Phase'] == key]
            return g

        for key, _ in df.groupby(gb_cols, sort=False):
            phase = key[0] if isinstance(key, tuple) else key
            g_lo = _subset_at(t_lo, key)
            g_hi = _subset_at(t_hi, key)
            if t_lo == t_hi or alpha == 0.0:
                g = g_lo if len(g_lo) >= 2 else g_hi
                x, y = _lmg_ordered_group_points(g, x_col, y_col)
            else:
                x_lo, y_lo = _lmg_ordered_group_points(g_lo, x_col, y_col)
                x_hi, y_hi = _lmg_ordered_group_points(g_hi, x_col, y_col)
                x, y = _interp_segment(x_lo, y_lo, x_hi, y_hi)
            _append_curve(phase, x, y)
    elif 'Phase' in df.columns:
        for phase in df['Phase'].dropna().unique():
            segs_lo = _lmg_segments_for_phase_at(df, t_lo, phase, x_col, y_col)
            segs_hi = _lmg_segments_for_phase_at(df, t_hi, phase, x_col, y_col)
            if t_lo == t_hi or alpha == 0.0:
                for x, y in (segs_lo or segs_hi):
                    _append_curve(phase, x, y)
            else:
                n_seg = max(len(segs_lo), len(segs_hi))
                for i in range(n_seg):
                    x_lo, y_lo = segs_lo[i] if i < len(segs_lo) else (np.array([]), np.array([]))
                    x_hi, y_hi = segs_hi[i] if i < len(segs_hi) else (np.array([]), np.array([]))
                    x, y = _interp_segment(x_lo, y_lo, x_hi, y_hi)
                    _append_curve(phase, x, y)

    return curves, t_lo, t_hi, note


def _lmg_collect_phase_scatter(df, x_col, y_col):
    """Per Phase: arrays of x, y, T for stacked surface plotting."""
    if 'Temperature_K' not in df.columns or 'Phase' not in df.columns:
        return {}
    out = {}
    for phase, gdf in df.groupby('Phase', sort=False):
        xv = pd.to_numeric(gdf[x_col], errors='coerce')
        yv = pd.to_numeric(gdf[y_col], errors='coerce')
        tv = pd.to_numeric(gdf['Temperature_K'], errors='coerce')
        m = xv.notna() & yv.notna() & tv.notna()
        if m.sum() < 3:
            continue
        out[str(phase)] = (xv.loc[m].to_numpy(), yv.loc[m].to_numpy(), tv.loc[m].to_numpy())
    return out


def _lmg_collect_stack_scatter(df, x_col, y_col):
    """All boundary points (x, y, T) stacked for one smooth temperature surface (ignores Phase)."""
    if 'Temperature_K' not in df.columns:
        return None
    xv = pd.to_numeric(df[x_col], errors='coerce')
    yv = pd.to_numeric(df[y_col], errors='coerce')
    tv = pd.to_numeric(df['Temperature_K'], errors='coerce')
    m = xv.notna() & yv.notna() & tv.notna()
    if m.sum() < 3:
        return None
    return xv.loc[m].to_numpy(), yv.loc[m].to_numpy(), tv.loc[m].to_numpy()


def _lmg_clip_z_to_min(z_values, t_min):
    """Clamp temperature values so the surface does not extend below data minimum (K)."""
    t_min = float(t_min)
    if z_values is None:
        return None
    out = np.asarray(z_values, dtype=np.float64)
    result = out.copy()
    finite = np.isfinite(result)
    result[finite] = np.maximum(result[finite], t_min)
    return result


def _lmg_iso_levels(z, interval_k):
    try:
        dk = float(interval_k)
    except (TypeError, ValueError):
        dk = 10.0
    if dk <= 0:
        dk = 10.0
    za = np.asarray(z, dtype=np.float64).ravel()
    za = za[np.isfinite(za)]
    if za.size == 0:
        return np.array([500.0, 600.0, 700.0], dtype=np.float64)
    zmin, zmax = float(za.min()), float(za.max())
    start = dk * np.ceil(zmin / dk)
    if start > zmax:
        return np.asarray([zmin], dtype=np.float64)
    return np.arange(start, zmax + 0.5 * dk, dk)


def _lmg_contour_segments(x_lin, y_lin, z2d, levels):
    if not MATPLOTLIB_AVAILABLE or z2d is None:
        return []
    out = []
    try:
        fig = plt.figure(figsize=(4, 3), dpi=72)
        ax = fig.add_subplot(111)
        cs = ax.contour(x_lin, y_lin, z2d, levels=levels)
        for li, lvl in enumerate(cs.levels):
            segs = cs.allsegs[li] if getattr(cs, 'allsegs', None) else []
            for seg in segs:
                if seg is not None and len(seg) >= 2:
                    out.append((float(lvl), np.asarray(seg, dtype=np.float64)))
        plt.close(fig)
    except Exception:
        try:
            plt.close('all')
        except Exception:
            pass
    return out


def _extp_trist_boundary_xyz(dfp, a_col, b_col):
    """Extract (x, y, T) arrays from TriST boundary / T0 line points."""
    ax = pd.to_numeric(dfp[a_col], errors='coerce')
    by = pd.to_numeric(dfp[b_col], errors='coerce')
    bt = pd.to_numeric(dfp.get('T (K)', np.nan), errors='coerce')
    m = ax.notna() & by.notna() & bt.notna()
    if not m.any():
        return (
            np.empty(0, dtype=np.float64),
            np.empty(0, dtype=np.float64),
            np.empty(0, dtype=np.float64),
        )
    return (
        ax.loc[m].to_numpy(dtype=np.float64),
        by.loc[m].to_numpy(dtype=np.float64),
        bt.loc[m].to_numpy(dtype=np.float64),
    )


def _extp_trist_draw_iso_3d_mpl(ax, xi, yi, zi, levels, line_color='#2c3e50', text_color='#1a252f', mid_frac=0.5, level_fmt='.0f'):
    """Draw labeled isocontours on a 3D Matplotlib surface."""
    for lvl, seg in _lmg_contour_segments(xi, yi, zi, levels):
        if seg is None or len(seg) < 2:
            continue
        ax.plot(seg[:, 0], seg[:, 1], np.full(len(seg), lvl, dtype=np.float64), color=line_color, linewidth=1.0)
        mid = int(max(0, min(len(seg) - 1, round((len(seg) - 1) * mid_frac))))
        ax.text(
            seg[mid, 0], seg[mid, 1], float(lvl), f'{lvl:{level_fmt}}',
            color=text_color, fontsize=8, fontweight='bold',
            ha='center', va='center',
            bbox=dict(boxstyle='round,pad=0.15', fc='white', alpha=0.78, edgecolor='none'),
        )


def _extp_trist_plotly_iso_traces(traces, lvl, seg, line_color, text_color, mid_frac=0.5, level_fmt='.0f'):
    """Append Plotly 3D isocontour line + value label traces."""
    if not PLOTLY_AVAILABLE or seg is None or len(seg) < 2:
        return
    traces.append(
        go.Scatter3d(
            x=seg[:, 0], y=seg[:, 1], z=np.full(len(seg), lvl, dtype=float),
            mode='lines', line=dict(color=line_color, width=3), showlegend=False,
        )
    )
    mid = int(max(0, min(len(seg) - 1, round((len(seg) - 1) * mid_frac))))
    traces.append(
        go.Scatter3d(
            x=[float(seg[mid, 0])], y=[float(seg[mid, 1])], z=[float(lvl)],
            mode='text', text=[f'{lvl:{level_fmt}}'],
            textfont=dict(color=text_color, size=11), showlegend=False,
        )
    )


def _pbfx_ordered_element_placeholders(content):
    """Element symbols (e.g. 'Li') in first-occurrence order from %[A-Za-z]%+ tokens."""
    order = []
    seen = set()
    for m in re.finditer(r'%([A-Za-z]+)%', content):
        el = m.group(1).title()
        if el in PERIODIC_TABLE and el not in seen:
            seen.add(el)
            order.append(el)
    return order


def _pbfx_default_output_name_pattern(stem_no_ext, ordered_elements):
    """
    Build default output basename (no .pbfx): e.g. T0-AlCuLi + %LI% only -> T0-AlCu%LI%Li.
    Suffix after %EL% uses canonical element symbols (Si, Li, …), not all-lowercase.
    Alloy prefixes (e.g. Gibbs_ALMGSI, Gibbs_ALCULI) are rewritten to Gibbs_AlMg%SI%Si / Gibbs_AlCu%LI%Li
    using template element order and periodic-table tokenization.
    For several placeholders, if the stem ends with the first element in template order, use that
    sweep-style pattern (balance the others via row removal or checkbox).
    """
    if not ordered_elements:
        return stem_no_ext
    o = ordered_elements
    
    # 1) Stem ends with concatenation of all elements in template order (variable-length symbols).
    rest = stem_no_ext
    for el in reversed(o):
        if len(rest) < len(el) or rest[-len(el):].lower() != el.lower():
            break
        rest = rest[:-len(el)]
    else:
        prefix = rest
        if len(o) == 1:
            sym = o[0]
            return prefix + '%' + sym.upper() + '%' + sym
        return prefix + ''.join(o[:-1]) + '%' + o[-1].upper() + '%' + o[-1]

    # 2) Trailing letter run equals the concatenation of all element symbols (e.g. ALCULI vs AlCuLi).
    m = re.search(r'([A-Za-z]+)$', stem_no_ext)
    if m:
        run = m.group(1)
        cat = ''.join(o)
        if run.lower() == cat.lower():
            prefix = stem_no_ext[: m.start(1)]
            if len(o) == 1:
                sym = o[0]
                return prefix + '%' + sym.upper() + '%' + sym
            return prefix + ''.join(o[:-1]) + '%' + o[-1].upper() + '%' + o[-1]

    # 3) Legacy: stem ends with first element in list (sweep that element).
    fe = o[0]
    if len(o) > 1 and len(stem_no_ext) >= len(fe) and stem_no_ext.lower().endswith(fe.lower()):
        prefix = _pbfx_canonicalize_trailing_element_run(stem_no_ext[: -len(fe)])
        return prefix + '%' + fe.upper() + '%' + fe

    # 4) Single element: strip trailing symbol; normalize remaining alloy prefix casing.
    if len(o) == 1:
        sym = o[0]
        if len(stem_no_ext) >= len(sym) and stem_no_ext.lower().endswith(sym.lower()):
            prefix = _pbfx_canonicalize_trailing_element_run(stem_no_ext[: -len(sym)])
            return prefix + '%' + sym.upper() + '%' + sym
        return stem_no_ext + '_%' + sym.upper() + '%'

    # 5) Fallback: normalize any trailing element run, then list placeholders.
    stem_norm = _pbfx_canonicalize_trailing_element_run(stem_no_ext)
    return stem_norm + '_' + '_'.join('%' + e.upper() + '%' for e in o)


def _pbfx_parse_composition_unit_base(content):
    """
    Read <unit name="n" value="..."/> from .pbfx content.
    Returns (balance_total, raw_token): w%/x% -> 100, w/x -> 1; unknown -> (100, raw or None).
    """
    m = re.search(
        r'<unit\s+[^>]*name\s*=\s*["\']n["\'][^>]*value\s*=\s*["\']([^"\']*)["\']',
        content,
        re.I,
    )
    if not m:
        m = re.search(
            r'<unit\s+[^>]*value\s*=\s*["\']([^"\']*)["\'][^>]*name\s*=\s*["\']n["\']',
            content,
            re.I,
        )
    if not m:
        return 100.0, None
    raw = (m.group(1) or '').strip()
    key = raw.lower()
    if key in ('w%',):
        return 100.0, raw
    if key in ('x%',):
        return 100.0, raw
    if key in ('w',):
        return 1.0, raw
    if key in ('x',):
        return 1.0, raw
    return 100.0, raw


def _pbfx_parse_temperature_unit_token(content):
    """
    Read <unit name="T" value="K/C/F"/> from .pbfx content.
    Returns raw token (e.g. 'K') or None if not found.
    """
    m = re.search(
        r'<unit\s+[^>]*name\s*=\s*["\']T["\'][^>]*value\s*=\s*["\']([^"\']*)["\']',
        content,
        re.I,
    )
    if not m:
        m = re.search(
            r'<unit\s+[^>]*value\s*=\s*["\']([^"\']*)["\'][^>]*name\s*=\s*["\']T["\']',
            content,
            re.I,
        )
    if not m:
        return None
    raw = (m.group(1) or '').strip()
    return raw or None


def _tcm_normalize_element_symbol(symbol):
    return canonical_element_symbol(symbol)


_TCM_SC_LINE_RE = re.compile(r'^\s*s-c\s+(.*)$', re.IGNORECASE)


def _tcm_parse_baseline_from_template0(template0_path):
    """Read baseline T and composition from Template0 s-c lines (single-point setup)."""
    baseline = {}
    with open(template0_path, 'r', encoding='utf-8') as f:
        for line in f:
            m = _TCM_SC_LINE_RE.match(line)
            if not m:
                continue
            rest = m.group(1)
            mt = re.search(r'\bt\s*=\s*([\d.]+(?:[eE][+-]?\d+)?)', rest, re.IGNORECASE)
            if mt:
                baseline['T'] = float(mt.group(1))
            for m2 in re.finditer(
                r'([wx])\s*\(\s*([A-Za-z]+)\s*\)\s*=\s*([\d.]+(?:[eE][+-]?\d+)?)',
                rest,
                re.IGNORECASE,
            ):
                el = _tcm_normalize_element_symbol(m2.group(2))
                baseline[el] = float(m2.group(3))
    return baseline


def _tcm_baseline_effective_zero(baseline_val):
    """True when Template0 uses a tiny w(*) substitute for a zero composition label."""
    bv = float(baseline_val)
    return bv <= 1e-4 or np.isclose(bv, float(TCM_SC_W_ZERO_COMP_STR), rtol=0.0, atol=1e-9)


def _tcm_composition_values_match(combo_val, baseline_val, out_decimals):
    if np.isclose(float(combo_val), float(baseline_val), rtol=0.0, atol=1e-9):
        return True
    if _tcm_is_zero_batch_comp(combo_val, out_decimals) and _tcm_baseline_effective_zero(baseline_val):
        return True
    return False


def _tcm_should_skip_loop_iteration(baseline, element_names, combo, t_val, out_decimals=2):
    """
    Skip emitting the loop-body block when this (composition, temperature) combination
    duplicates the single-point calculation already present in Template0.
    """
    if not baseline:
        return False

    if element_names:
        comp_matches = True
        for i, el in enumerate(element_names):
            bel = baseline.get(el)
            if bel is None:
                comp_matches = False
                break
            if not _tcm_composition_values_match(combo[i], bel, out_decimals):
                comp_matches = False
                break
    else:
        comp_matches = True

    if t_val is not None and 'T' in baseline:
        t_matches = np.isclose(float(t_val), float(baseline['T']), rtol=0.0, atol=1e-9)
    elif t_val is not None:
        t_matches = False
    else:
        t_matches = True

    if element_names and t_val is not None:
        return t_matches and comp_matches
    if element_names:
        return comp_matches
    if t_val is not None:
        return t_matches
    return False


TCM_SC_W_ZERO_COMP_STR = '0.00001'


def _tcm_is_sc_w_composition_line(line):
    """True for Thermo-Calc ``s-c w(element)=...`` composition setup lines."""
    return bool(re.match(r'^\s*s-c\s+w\s*\(\s*[^)]+\s*\)\s*=', line, re.IGNORECASE))


def _tcm_is_zero_batch_comp(val, out_decimals):
    """True when a loop composition formats to 0.00 (etc.) at the chosen precision."""
    fv = float(val)
    fmt_zero = f"{0.0:.{out_decimals}f}"
    return f"{fv:.{out_decimals}f}" == fmt_zero


def _exptc_format_comp_token(val):
    """Format a composition value for Al0.005Cu0.000Li-style TCM filenames."""
    fv = float(val)
    if abs(fv) < 1e-12:
        return '0.000'
    s = f"{fv:.6f}".rstrip('0').rstrip('.')
    return s if s else '0'


def _exptc_format_placeholder_value(val):
    fv = float(val)
    if abs(fv) < 1e-12:
        return '0.000'
    s = f"{fv:.6f}".rstrip('0').rstrip('.')
    return s if s else '0'


def _exptc_record_to_placeholder_values(rec):
    ph = {}
    for k, v in rec.items():
        if not isinstance(k, str) or not k.lower().startswith('w('):
            continue
        m = re.match(r'w\(([^)]+)\)', k, re.I)
        if not m:
            continue
        el_raw = m.group(1)
        if re.match(r'element', el_raw, re.I):
            continue
        el = _tcm_normalize_element_symbol(el_raw)
        if el:
            ph[el] = _exptc_format_placeholder_value(v)
    if rec.get('Temperature_K') is not None:
        t = float(rec['Temperature_K'])
        ph['T'] = f"{int(t)}" if abs(t - round(t)) < 1e-6 else f"{t:g}"
    return ph


def _exptc_apply_template1(template_text, placeholder_values):
    upper_to_val = {k.upper(): v for k, v in placeholder_values.items()}

    def _repl(m):
        u = m.group(1).upper()
        if u in upper_to_val:
            return upper_to_val[u]
        return m.group(0)

    return re.sub(r'%([A-Za-z]+)%', _repl, template_text)


def _exptc_dedupe_error_records(records):
    seen = set()
    out = []
    for rec in records:
        key_parts = []
        for k, v in sorted(rec.items()):
            if k == 'file':
                continue
            if isinstance(k, str) and k.lower().startswith('w('):
                try:
                    key_parts.append((k, float(v)))
                except (TypeError, ValueError):
                    key_parts.append((k, v))
            elif k == 'Temperature_K' and v is not None:
                try:
                    key_parts.append(('T', float(v)))
                except (TypeError, ValueError):
                    key_parts.append(('T', v))
        key = tuple(key_parts)
        if key in seen:
            continue
        seen.add(key)
        out.append(rec)
    return out


def _exptc_comp_basename_from_record(rec):
    w_items = []
    for k, v in rec.items():
        if not isinstance(k, str) or not k.lower().startswith('w('):
            continue
        m = re.match(r'w\(([^)]+)\)', k, re.I)
        if not m:
            continue
        el_raw = m.group(1)
        if re.match(r'element', el_raw, re.I):
            continue
        el = _tcm_normalize_element_symbol(el_raw)
        if el:
            try:
                w_items.append((el, float(v)))
            except (TypeError, ValueError):
                pass
    if w_items:
        w_items.sort(key=lambda x: x[0])
        stem = 'Al'
        for el, val in w_items:
            stem += _exptc_format_comp_token(val) + el
        if rec.get('Temperature_K') is not None:
            t = float(rec['Temperature_K'])
            stem += f"_{int(t) if abs(t - round(t)) < 1e-6 else t:g}K"
        return stem
    base = os.path.splitext(os.path.basename(rec.get('file', 'abnormal')))[0]
    if rec.get('Temperature_K') is not None:
        t = float(rec['Temperature_K'])
        base += f"_{int(t) if abs(t - round(t)) < 1e-6 else t:g}K"
    return re.sub(r'[^\w.-]', '_', base)


def _exptc_generate_abnormal_tcm_files(template1_path, output_dir, error_records):
    if not error_records:
        return 0, []
    with open(template1_path, 'r', encoding='utf-8') as f:
        template_text = f.read()
    os.makedirs(output_dir, exist_ok=True)
    deduped = _exptc_dedupe_error_records(error_records)
    written = []
    used_names = set()
    for rec in deduped:
        ph = _exptc_record_to_placeholder_values(rec)
        content = _exptc_apply_template1(template_text, ph)
        base = _exptc_comp_basename_from_record(rec)
        fname = base
        n = 2
        while fname in used_names:
            fname = f"{base}_{n}"
            n += 1
        used_names.add(fname)
        out_path = os.path.join(output_dir, fname + '.tcm')
        with open(out_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)
        written.append(out_path)
    return len(written), written


EXPTC_GIBBS_FILTER_DEFAULT = r'.*_Gibbs\.exp$'

_TCM_GIBBS_PLOTTED_RE = re.compile(
    r'^\s*\$\s*PLOTTED\s+COLUMNS\s+ARE\s*:\s*W\(([^)]+)\)\s+and\s+GMR\(([^)]+)\)\s*$',
    re.IGNORECASE,
)


def _exptc_gibbs_snap_mass_fraction(v, eps=1e-7):
    try:
        fv = float(v)
    except (TypeError, ValueError):
        return v
    return 0.0 if abs(fv) < eps else fv


def _exptc_gibbs_parse_filename(file_name):
    """
    Parse Thermo-Calc Gibbs .exp names such as AlCu-0.050Li_650T_Gibbs.exp
    -> (fixed_element, fixed_w, T_K).
    """
    patterns = (
        r'[-_](\d+(?:\.\d+)?)([A-Za-z]{1,2})_(\d+(?:\.\d+)?)T_Gibbs\.exp$',
        r'(\d+(?:\.\d+)?)([A-Za-z]{1,2})_(\d+(?:\.\d+)?)T_Gibbs\.exp$',
    )
    for pat in patterns:
        m = re.search(pat, file_name, flags=re.IGNORECASE)
        if m:
            return canonical_element_symbol(m.group(2)), float(m.group(1)), float(m.group(3))
    return None, None, None


def _exptc_gibbs_normalize_phase(gmr_phase):
    ph = str(gmr_phase).strip().upper()
    ph = re.sub(r'#+\d+$', '', ph)
    return ph


def _exptc_gibbs_extract_from_exp(file_path):
    """
    Parse Thermo-Calc Gibbs .exp: XTEXT W(*) scan axis and GMR(phase) sections
    marked by '$ PLOTTED COLUMNS ARE : W(*) and GMR(PHASE)'.
    Returns (scan_element, {phase: [(w_scan, gmr_j_mol), ...]}).
    """
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except Exception:
        return None, {}

    scan_el = None
    for line in lines[:80]:
        m = re.search(r'^\s*XTEXT\s+W\(([^)]+)\)', line.strip(), flags=re.IGNORECASE)
        if m:
            scan_el = canonical_element_symbol(m.group(1))
            break

    phase_data = {}
    current_phase = None
    for line in lines:
        s = line.strip()
        m_pl = _TCM_GIBBS_PLOTTED_RE.match(s)
        if m_pl:
            if scan_el is None:
                scan_el = canonical_element_symbol(m_pl.group(1))
            current_phase = _exptc_gibbs_normalize_phase(m_pl.group(2))
            phase_data.setdefault(current_phase, [])
            continue
        if s.startswith('BLOCKEND'):
            current_phase = None
            continue
        if current_phase and s and not s.startswith('$'):
            parts = s.split()
            if len(parts) >= 2:
                try:
                    x = float(parts[0])
                    y = float(parts[1])
                    phase_data[current_phase].append((x, y))
                except ValueError:
                    continue

    # De-duplicate scan points per phase (keep last occurrence)
    for ph, pts in list(phase_data.items()):
        dedup = {}
        for x, y in pts:
            dedup[round(float(x), 12)] = float(y)
        phase_data[ph] = sorted(dedup.items(), key=lambda t: t[0])

    return scan_el, phase_data


def _exptc_gibbs_pick_solid_phase(phase_data):
    solids = {k: v for k, v in phase_data.items() if 'LIQUID' not in str(k).upper()}
    if not solids:
        return None
    return max(solids.keys(), key=lambda k: len(solids[k]))


def _exptc_gibbs_file_to_merged_df(file_path, file_name):
    fixed_el, fixed_val, t_k = _exptc_gibbs_parse_filename(file_name)
    if fixed_el is None or t_k is None:
        return None, 'bad_filename'
    scan_el, phase_data = _exptc_gibbs_extract_from_exp(file_path)
    if not scan_el or not phase_data:
        return None, 'no_gmr_data'
    liq_key = next((k for k in phase_data if 'LIQUID' in str(k).upper()), None)
    if liq_key is None:
        return None, 'no_liquid'
    sol_key = _exptc_gibbs_pick_solid_phase(phase_data)
    if sol_key is None:
        return None, 'no_solid'

    liq_map = dict(phase_data[liq_key])
    sol_map = dict(phase_data[sol_key])
    rows = []
    for x, g_liq in liq_map.items():
        g_sol = sol_map.get(x)
        if g_sol is None:
            for xk, gs in sol_map.items():
                if abs(float(xk) - float(x)) <= 1e-8:
                    g_sol = gs
                    break
        if g_sol is None:
            continue
        w_fixed = _exptc_gibbs_snap_mass_fraction(fixed_val)
        w_scan = _exptc_gibbs_snap_mass_fraction(x)
        dg = float(g_sol) - float(g_liq)
        rows.append(
            {
                'File': file_name,
                'Path': file_path,
                'T (K)': float(t_k),
                f'w({fixed_el})': w_fixed,
                f'w({scan_el})': w_scan,
                'G_liquid (J/mol)': float(g_liq),
                'G_solid (J/mol)': float(g_sol),
                'phase (solid)': sol_key,
                'phase (liquid)': 'LIQUID',
                'dG = G_solid - G_liquid (J/mol)': dg,
                'in_TriST dG le 0': int(dg <= 0),
            }
        )
    if not rows:
        return None, 'no_pairs'
    return pd.DataFrame(rows), None


def _exptc_collect_gibbs_exp_files(folder, name_filter=None):
    """Collect .exp files from folder (recursive)."""
    out = []
    for root, _dirs, files in os.walk(folder):
        for fn in files:
            if not fn.lower().endswith('.exp'):
                continue
            if name_filter is not None and not name_filter.match(fn):
                continue
            out.append(os.path.join(root, fn))
    return sorted(out)


def _exptc_gibbs_peek_axis_sample(folder, name_filter=None, max_files=12):
    """
    Parse a few Gibbs .exp files in folder and return available w(*) columns
    plus a small merged sample (for _extp_trist_pick_axes_2d).
    """
    files = _exptc_collect_gibbs_exp_files(folder, name_filter)
    blocks = []
    for path in files[:max_files]:
        m, _err = _exptc_gibbs_file_to_merged_df(path, os.path.basename(path))
        if m is not None:
            blocks.append(m)
    if not blocks:
        return [], None
    sample = pd.concat(blocks, ignore_index=True)
    wcols = [
        c for c in sample.columns
        if isinstance(c, str) and re.match(r'^\s*w\([A-Za-z]{1,3}\)\s*$', c)
    ]
    wcols = list(dict.fromkeys(wcols))
    return wcols, sample


def _extp_trist_build_and_save_workbook(merged_all, x_col, y_col, ngrid, out_path, log_fn=None, tr=None):
    """
    Compute T0_lines / TriST_boundaries / TriST_mask / optional _trist_cube.npz
    from merged Gibbs rows (same schema as Pandat TriST extract).
    """
    if tr is None:
        tr = lambda k, d='': d
    if log_fn is None:
        log_fn = lambda _m: None
    if not SCIPY_AVAILABLE or not MATPLOTLIB_AVAILABLE:
        raise RuntimeError('scipy and matplotlib are required for TriST workbook generation.')

    tcol = 'T (K)'
    gl_col = 'G_liquid (J/mol)'
    gs_col = 'G_solid (J/mol)'
    df_pts = merged_all[[tcol, x_col, y_col, gl_col, gs_col]].copy()
    for c in (tcol, x_col, y_col, gl_col, gs_col):
        df_pts[c] = pd.to_numeric(df_pts[c], errors='coerce')
    df_pts = df_pts.dropna(subset=[tcol, x_col, y_col, gl_col, gs_col])
    if df_pts.empty:
        raise ValueError(tr('extp_trist_no_data', 'No merged rows.'))

    ngrid = max(25, min(160, int(ngrid)))
    t0_rows, bnd_rows, mask_rows = [], [], []
    f_cube_list, T_cube_list = [], []
    temps = sorted(df_pts[tcol].unique().tolist())
    g_xmin = float(np.nanmin(df_pts[x_col].to_numpy(dtype=np.float64)))
    g_xmax = float(np.nanmax(df_pts[x_col].to_numpy(dtype=np.float64)))
    g_ymin = float(np.nanmin(df_pts[y_col].to_numpy(dtype=np.float64)))
    g_ymax = float(np.nanmax(df_pts[y_col].to_numpy(dtype=np.float64)))
    if g_xmax - g_xmin < 1e-9 or g_ymax - g_ymin < 1e-9:
        raise ValueError(tr('extp_trist_no_data', 'No merged rows.'))
    x_lin = np.linspace(g_xmin, g_xmax, ngrid)
    y_lin = np.linspace(g_ymin, g_ymax, ngrid)
    gx, gy = np.meshgrid(x_lin, y_lin)

    for ti, Tval in enumerate(temps, start=1):
        if ti % 10 == 1:
            log_fn(tr('extp_trist_progress', 'Processing {i} / {n}…').format(i=ti, n=len(temps)))
        sub = df_pts[df_pts[tcol] == Tval]
        if len(sub) < 8:
            continue
        xs = sub[x_col].to_numpy(dtype=np.float64)
        ys = sub[y_col].to_numpy(dtype=np.float64)
        gls = sub[gl_col].to_numpy(dtype=np.float64)
        gss = sub[gs_col].to_numpy(dtype=np.float64)
        gl_grid = _extp_trist_grid_surface(np.column_stack([xs, ys]), gls, gx, gy)
        gs_grid = _extp_trist_grid_surface(np.column_stack([xs, ys]), gss, gx, gy)
        if gl_grid is None or gs_grid is None:
            continue
        gl_grid = np.asarray(gl_grid, dtype=np.float64)
        gs_grid = np.asarray(gs_grid, dtype=np.float64)
        valid = np.isfinite(gl_grid) & np.isfinite(gs_grid)
        if valid.sum() < 25:
            continue
        dg_grid = gs_grid - gl_grid
        dg_masked = np.ma.array(dg_grid, mask=~valid)
        for ci, v in enumerate(_extp_trist_contours_xy(x_lin, y_lin, dg_masked, level=0.0)):
            for pi, (xv, yv) in enumerate(v):
                t0_rows.append({'T (K)': float(Tval), 'curve_id': int(ci), 'point_i': int(pi), x_col: float(xv), y_col: float(yv)})

        dx = float(x_lin[1] - x_lin[0])
        dy = float(y_lin[1] - y_lin[0])
        dGL_dy, dGL_dx = np.gradient(gl_grid, dy, dx)
        mu_x = np.asarray(dGL_dx, dtype=np.float64)
        mu_y = np.asarray(dGL_dy, dtype=np.float64)
        Xg = gx.astype(np.float64)
        Yg = gy.astype(np.float64)
        t0_side = valid & (gl_grid <= gs_grid)
        cand_mask = t0_side & np.isfinite(mu_x) & np.isfinite(mu_y)
        if cand_mask.sum() < 25:
            continue
        GSf = gs_grid.reshape(-1)
        Xf = Xg.reshape(-1)
        Yf = Yg.reshape(-1)
        dom = valid.reshape(-1) & np.isfinite(GSf) & np.isfinite(Xf) & np.isfinite(Yf)
        GSf, Xf, Yf = GSf[dom], Xf[dom], Yf[dom]
        if len(GSf) < 50:
            continue
        mux0 = mu_x[cand_mask]
        muy0 = mu_y[cand_mask]
        x0 = Xg[cand_mask]
        y0 = Yg[cand_mask]
        gl0 = gl_grid[cand_mask]
        mvals = np.empty(len(mux0), dtype=np.float64)
        chunk = 256
        for s in range(0, len(mux0), chunk):
            e = min(s + chunk, len(mux0))
            mu_xc = mux0[s:e][:, None]
            mu_yc = muy0[s:e][:, None]
            vals = GSf[None, :] - mu_xc * Xf[None, :] - mu_yc * Yf[None, :]
            mvals[s:e] = np.nanmin(vals, axis=1)
        fvals = mvals - (gl0 - mux0 * x0 - muy0 * y0)
        f_grid = np.full_like(gl_grid, np.nan, dtype=np.float64)
        f_grid[cand_mask] = fvals
        f_cube_list.append(np.ascontiguousarray(f_grid, dtype=np.float32))
        T_cube_list.append(float(Tval))
        f_masked = np.ma.array(f_grid, mask=~cand_mask | ~np.isfinite(f_grid))
        for ci, v in enumerate(_extp_trist_contours_xy(x_lin, y_lin, f_masked, level=0.0)):
            for pi, (xv, yv) in enumerate(v):
                bnd_rows.append({'T (K)': float(Tval), 'curve_id': int(ci), 'point_i': int(pi), x_col: float(xv), y_col: float(yv)})
        inside = cand_mask & np.isfinite(f_grid) & (f_grid <= 0.0)
        if inside.any():
            ii, jj = np.where(inside)
            cap = 12000
            if len(ii) > cap:
                step = int(np.ceil(len(ii) / cap))
                ii, jj = ii[::step], jj[::step]
            for k2 in range(len(ii)):
                i2, j2 = int(ii[k2]), int(jj[k2])
                mask_rows.append({'T (K)': float(Tval), x_col: float(gx[i2, j2]), y_col: float(gy[i2, j2]), 'inside_TriST': 1, 'f(C0) (J/mol)': float(f_grid[i2, j2])})

    if len(f_cube_list) >= 2:
        try:
            cube_path = os.path.splitext(out_path)[0] + '_trist_cube.npz'
            np.savez_compressed(
                cube_path,
                T_vals=np.asarray(T_cube_list, dtype=np.float64),
                x_lin=np.asarray(x_lin, dtype=np.float64),
                y_lin=np.asarray(y_lin, dtype=np.float64),
                f_cube=np.stack(f_cube_list, axis=0),
                x_col=str(x_col),
                y_col=str(y_col),
            )
            log_fn(tr('extp_trist_cube_log', 'Saved 3D f(C0) field (for smooth f=0 surface, cubic in T): {path}').format(path=cube_path))
        except Exception as e:
            log_fn(tr('extp_trist_cube_err', 'Could not save 3D f-field: {e}').format(e=str(e)))

    t0_df = pd.DataFrame(t0_rows)
    bnd_df = pd.DataFrame(bnd_rows)
    mask_df = pd.DataFrame(mask_rows)
    with pd.ExcelWriter(out_path, engine='openpyxl') as xw:
        pd.DataFrame().to_excel(xw, sheet_name='T0_tie_1D', index=False)
        t0_df.to_excel(xw, sheet_name='T0_lines', index=False)
        bnd_df.to_excel(xw, sheet_name='TriST_boundaries', index=False)
        mask_df.to_excel(xw, sheet_name='TriST_mask', index=False)
    return t0_df, bnd_df, mask_df


def _extp_trist_find_col_df(df, names):
    if df is None or not hasattr(df, 'columns'):
        return None
    cols_upper = {str(c).strip().upper(): c for c in df.columns if isinstance(c, str)}
    for n in names:
        nu = str(n).strip().upper()
        if nu in cols_upper:
            return cols_upper[nu]
    return None


def _extp_trist_pandat_g_columns(df):
    """
    Find liquid and solid molar Gibbs energy columns in Pandat All table_Gibbs exports
    (e.g. G(@LIQUID:FCC_A1[*]) and G(@FCC_A1:FCC_A1[*])).
    """
    gcols = [c for c in df.columns if isinstance(c, str) and c.strip().startswith('G(')]
    g_liq, g_sol = None, None
    for c in gcols:
        if re.search(r'LIQUID', c, re.I):
            g_liq = c
    for c in gcols:
        if c == g_liq:
            continue
        u = c.upper()
        if 'FCC' in u or 'BCC' in u or 'HCP' in u:
            g_sol = c
            break
    if g_sol is None and gcols:
        for c in gcols:
            if c != g_liq:
                g_sol = c
                break
    return g_liq, g_sol


def _extp_trist_w_columns(df):
    out = []
    for c in df.columns:
        if not isinstance(c, str):
            continue
        m = re.match(r'^\s*w\(\s*([A-Za-z]+)\s*\)\s*$', c, re.IGNORECASE)
        if m:
            el = m.group(1).title()
            out.append((c, f"w({el})"))
    return out


def _extp_trist_merge_solid_liquid(
    df,
    phase_col,
    t_col,
    g_liq,
    g_sol,
    w_map,
    path_label,
    file_name,
):
    """
    Pair LIQUID and solid (FCC/BCC) rows at the same (T, w*) and return rows with
    G_solid, G_liquid, dG = G_solid - G_liquid.
    w_map: list of (orig_col, canonical_name) for w(*) columns.
    """
    wcols = [a for a, _ in w_map]
    ren = {a: b for a, b in w_map}
    p = df[phase_col].astype(str)
    p_up = p.str.upper()
    m_sol = p_up.str.contains('FCC', na=False) | p_up.str.contains('BCC', na=False) | p_up.str.contains('HCP', na=False)
    m_liq = p_up.str.contains('LIQUID', na=False)
    if m_sol.sum() < 1 or m_liq.sum() < 1:
        m_liq = p_up.str.contains('LIQUID', na=False)
        m_sol = ~m_liq
    tname = 'T (K)'
    ds = df.loc[m_sol, [t_col, phase_col, g_sol] + wcols].copy()
    dl = df.loc[m_liq, [t_col, g_liq] + wcols].copy()
    ds = ds.rename(columns=ren)
    ds = ds.rename(columns={t_col: tname, g_sol: 'G_solid (J/mol)'})
    ds['phase (solid)'] = ds[phase_col].astype(str)
    ds = ds.drop(columns=[phase_col], errors='ignore')
    dl = dl.rename(columns=ren)
    dl = dl.rename(columns={t_col: tname, g_liq: 'G_liquid (J/mol)'})
    key = [tname] + [b for _, b in w_map]
    for d in (ds, dl):
        for c in key:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    for c in key[1:]:
        ds[c] = ds[c].round(10)
        dl[c] = dl[c].round(10)
    ds['G_solid (J/mol)'] = pd.to_numeric(ds['G_solid (J/mol)'], errors='coerce')
    dl['G_liquid (J/mol)'] = pd.to_numeric(dl['G_liquid (J/mol)'], errors='coerce')
    m = pd.merge(ds, dl, on=key, how='inner')
    if m.empty:
        return None, 'no_inner_join'
    m['dG = G_solid - G_liquid (J/mol)'] = m['G_solid (J/mol)'] - m['G_liquid (J/mol)']
    m.insert(0, 'File', file_name)
    m.insert(1, 'Path', path_label)
    m['phase (liquid)'] = 'LIQUID'
    m['in_TriST dG le 0'] = (m['dG = G_solid - G_liquid (J/mol)'] <= 0).astype(int)
    return m, None


def _extp_trist_interp_t0_1d(merged, wcols_canon):
    """
    Along the composition coordinate with the largest w-range, find (w*) where dG crosses zero
    by linear interpolation; all w components are interpolated along the same segment.
    """
    if merged is None or len(merged) < 2:
        return None
    dgcol = 'dG = G_solid - G_liquid (J/mol)'
    if dgcol not in merged.columns:
        return None
    sub = merged.copy()
    sub[dgcol] = pd.to_numeric(sub[dgcol], errors='coerce')
    sub = sub.dropna(subset=[dgcol])
    if len(sub) < 2:
        return None
    ranges = {}
    for c in wcols_canon:
        if c in sub.columns:
            x = pd.to_numeric(sub[c], errors='coerce')
            if x.notna().any():
                ranges[c] = float(x.max() - x.min())
    if not ranges:
        return None
    scan = max(ranges, key=ranges.get)
    sub = sub.sort_values(scan)
    dg = sub[dgcol].to_numpy(dtype=np.float64)
    out = {'T (K)': float(pd.to_numeric(sub['T (K)'], errors='coerce').iloc[0])}
    out['T0 scan axis (max w range)'] = scan
    for i in range(len(dg) - 1):
        if abs(dg[i]) < 1e-9:
            for c in wcols_canon:
                if c in sub.columns:
                    out[c] = float(sub[c].to_numpy()[i])
            out['dG (J/mol)'] = 0.0
            out['interp'] = 'on_grid'
            return out
        if dg[i] * dg[i + 1] < 0:
            tfrac = -dg[i] / (dg[i + 1] - dg[i])
            for c in wcols_canon:
                if c not in sub.columns:
                    continue
                wc = sub[c].to_numpy(dtype=np.float64)
                out[c] = float(wc[i] + tfrac * (wc[i + 1] - wc[i]))
            out['dG (J/mol)'] = 0.0
            out['interp'] = 'linear'
            return out
    if np.isfinite(dg).all() and len(dg) > 0 and np.nanmin(np.abs(dg)) < 0.1:
        j = int(np.nanargmin(np.abs(dg)))
        for c in wcols_canon:
            if c in sub.columns:
                out[c] = float(sub[c].to_numpy()[j])
        out['dG (J/mol)'] = float(dg[j])
        out['interp'] = 'near_zero'
        return out
    return None


def _ternary_to_xy(a, b, c):
    """Map ternary (a,b,c) to 2D coordinates; a+b+c may be 1 or 100."""
    s = a + b + c
    if not np.isfinite(s) or abs(s) < 1e-12:
        return np.nan, np.nan
    x = 0.5 * (2.0 * b + c) / s
    y = (np.sqrt(3.0) / 2.0) * c / s
    return x, y


def _extp_trist_pick_ternary_wcols(df):
    """Pick up to 3 w(*) columns (prefer those with largest variance)."""
    if df is None or not hasattr(df, 'columns'):
        return []
    wcols = [c for c in df.columns if isinstance(c, str) and re.match(r'^\s*w\([A-Za-z]{1,3}\)\s*$', c)]
    if len(wcols) <= 3:
        return wcols
    vars_ = []
    for c in wcols:
        x = pd.to_numeric(df[c], errors='coerce')
        vars_.append((float(x.var(skipna=True)) if x.notna().any() else 0.0, c))
    vars_.sort(reverse=True)
    return [c for _, c in vars_[:3]]


def _extp_trist_pick_axes_2d(df):
    """Pick two w(*) columns for 2D composition plane (highest variance)."""
    wcols = [c for c in _extp_trist_pick_ternary_wcols(df) if isinstance(c, str) and c.strip().lower().startswith('w(')]
    if len(wcols) >= 2:
        return wcols[0], wcols[1]
    # fallback: any w columns
    if df is None or not hasattr(df, 'columns'):
        return None, None
    wcols2 = [c for c in df.columns if isinstance(c, str) and re.match(r'^\s*w\([A-Za-z]{1,3}\)\s*$', c)]
    if len(wcols2) >= 2:
        return wcols2[0], wcols2[1]
    return None, None


def _extp_trist_grid_surface(points_xy, values, gx, gy):
    """
    Interpolate scattered points onto (gx, gy) grid.
    Prefer cubic; fallback to linear then nearest for NaN fill.
    """
    if points_xy is None or len(points_xy) < 4:
        return None
    if not SCIPY_AVAILABLE:
        return None
    pts = np.asarray(points_xy, dtype=np.float64)
    vals = np.asarray(values, dtype=np.float64)
    try:
        zi = griddata(pts, vals, (gx, gy), method='cubic')
    except Exception:
        zi = None
    if zi is None:
        try:
            zi = griddata(pts, vals, (gx, gy), method='linear')
        except Exception:
            zi = None
    if zi is None:
        return None
    # fill NaNs progressively
    if np.isnan(zi).any():
        try:
            zlin = griddata(pts, vals, (gx, gy), method='linear')
            zi = np.where(np.isnan(zi), zlin, zi)
        except Exception:
            pass
    if np.isnan(zi).any():
        try:
            znn = griddata(pts, vals, (gx, gy), method='nearest')
            zi = np.where(np.isnan(zi), znn, zi)
        except Exception:
            pass
    return zi


def _extp_trist_contours_xy(x_lin, y_lin, z2d, level=0.0):
    """Return list of (n,2) vertices for contour z=level."""
    if not MATPLOTLIB_AVAILABLE:
        return []
    if z2d is None:
        return []
    try:
        fig = plt.figure(figsize=(4, 3), dpi=72)
        ax = fig.add_subplot(111)
        cs = ax.contour(x_lin, y_lin, z2d, levels=[level])
        out = []
        # Use allsegs to avoid deprecated collections access in Matplotlib >=3.8.
        segs = cs.allsegs[0] if getattr(cs, "allsegs", None) else []
        for v in segs:
            if v is not None and len(v) >= 2:
                out.append(np.asarray(v, dtype=np.float64))
        plt.close(fig)
        return out
    except Exception:
        try:
            plt.close('all')
        except Exception:
            pass
        return []


def _extp_trist_filled_f_for_rgi(f_arr):
    """Replace non-finite values so RegularGridInterpolator can use cubic method."""
    a = np.asarray(f_arr, dtype=np.float64)
    a = np.where(np.isfinite(a), a, 1.0e9)
    return a


def _extp_trist_dense_f_volume(T_vals, y_lin, x_lin, f_cube):
    """
    Interpolate saved f(C0) cube onto a dense (T, y, x) grid.
    Returns (Tq, y_lin, x_lin, Vt, V_plot) where Vt is (nt, ny, nx) and V_plot is (nx, ny, nt) for Plotly.
    """
    if not SCIPY_AVAILABLE:
        return None
    T1 = np.asarray(T_vals, dtype=np.float64).ravel()
    y_lin = np.asarray(y_lin, dtype=np.float64).ravel()
    x_lin = np.asarray(x_lin, dtype=np.float64).ravel()
    if T1.size < 2 or y_lin.size < 2 or x_lin.size < 2:
        return None
    order = np.argsort(T1, kind="mergesort")
    T1 = T1[order]
    f3 = np.asarray(f_cube, dtype=np.float64)
    if f3.ndim == 3 and f3.shape[0] == T1.size:
        f3 = f3[order]
    if f3.ndim != 3 or f3.shape[0] != T1.size:
        return None
    f_fill = _extp_trist_filled_f_for_rgi(f3)
    method = "cubic" if T1.size >= 4 and f_fill.shape[1] >= 4 and f_fill.shape[2] >= 4 else "linear"
    try:
        rgi = RegularGridInterpolator((T1, y_lin, x_lin), f_fill, method=method, bounds_error=False, fill_value=np.nan)
    except Exception:
        rgi = RegularGridInterpolator((T1, y_lin, x_lin), f_fill, method="linear", bounds_error=False, fill_value=np.nan)
    t_lo, t_hi = float(T1[0]), float(T1[-1])
    n_t = int(max(32, min(200, 4 * T1.size)))
    Tq = np.linspace(t_lo, t_hi, n_t)
    T3, Y3, X3 = np.meshgrid(Tq, y_lin, x_lin, indexing="ij")
    pts = np.stack((T3, Y3, X3), -1)
    Vt = rgi(pts)
    V_plot = np.transpose(Vt, (2, 1, 0)).astype(np.float64)
    return Tq, y_lin, x_lin, Vt, V_plot


def _extp_trist_clip_cube(T_vals, y_lin, x_lin, f_cube, px0=None, px1=None, py0=None, py1=None, tmin=None, tmax=None):
    """Slice the saved f(C0) cube to user XY/T bounds."""
    T_vals = np.asarray(T_vals, dtype=np.float64).ravel()
    y_lin = np.asarray(y_lin, dtype=np.float64).ravel()
    x_lin = np.asarray(x_lin, dtype=np.float64).ravel()
    f_cube = np.asarray(f_cube, dtype=np.float64)
    if f_cube.ndim != 3:
        return None
    t_mask = np.ones(T_vals.shape, dtype=bool)
    y_mask = np.ones(y_lin.shape, dtype=bool)
    x_mask = np.ones(x_lin.shape, dtype=bool)
    if tmin is not None and str(tmin).strip() != "" and np.isfinite(float(tmin)):
        t_mask &= T_vals >= float(tmin)
    if tmax is not None and str(tmax).strip() != "" and np.isfinite(float(tmax)):
        t_mask &= T_vals <= float(tmax)
    if px0 is not None and np.isfinite(float(px0)):
        x_mask &= x_lin >= float(px0)
    if px1 is not None and np.isfinite(float(px1)):
        x_mask &= x_lin <= float(px1)
    if py0 is not None and np.isfinite(float(py0)):
        y_mask &= y_lin >= float(py0)
    if py1 is not None and np.isfinite(float(py1)):
        y_mask &= y_lin <= float(py1)
    if t_mask.sum() < 2 or y_mask.sum() < 2 or x_mask.sum() < 2:
        return None
    f2 = f_cube[np.ix_(t_mask, y_mask, x_mask)]
    return T_vals[t_mask], y_lin[y_mask], x_lin[x_mask], f2


def _extp_trist_f_for_viz_volume(V_plot):
    """Mask f grid for Plotly Volume: only finite f <= 0 kept."""
    V = np.asarray(V_plot, dtype=np.float64).copy()
    V[~np.isfinite(V)] = np.nan
    V[V > 0.0] = np.nan
    return V


def _extp_trist_filter_df_xy(df, a_col, b_col, px0, px1, py0, py1):
    if df is None or df.empty or a_col not in df.columns or b_col not in df.columns:
        return df
    out = df.copy()
    av = pd.to_numeric(out[a_col], errors='coerce')
    bv = pd.to_numeric(out[b_col], errors='coerce')
    m = av.notna() & bv.notna() & (av >= px0) & (av <= px1) & (bv >= py0) & (bv <= py1)
    return out.loc[m]


def _extp_trist_clip_mesh_faces(xs, ys, zs, faces, px0, px1, py0, py1, tmin=None, tmax=None):
    """Keep only triangle/face centroids inside the plot box."""
    if faces is None or len(faces) == 0:
        return faces
    xs = np.asarray(xs, dtype=np.float64)
    ys = np.asarray(ys, dtype=np.float64)
    zs = np.asarray(zs, dtype=np.float64)
    faces = np.asarray(faces, dtype=np.int32)
    cx = xs[faces].mean(axis=1)
    cy = ys[faces].mean(axis=1)
    cz = zs[faces].mean(axis=1)
    keep = (
        (cx >= px0) & (cx <= px1) & (cy >= py0) & (cy <= py1) &
        np.isfinite(cx) & np.isfinite(cy) & np.isfinite(cz)
    )
    if tmin is not None and str(tmin).strip() != "" and np.isfinite(float(tmin)):
        keep &= cz >= float(tmin)
    if tmax is not None and str(tmax).strip() != "" and np.isfinite(float(tmax)):
        keep &= cz <= float(tmax)
    return faces[keep] if keep.any() else np.empty((0, 3), dtype=np.int32)


def _extp_trist_default_coord_limits(x_min, x_max, y_min, y_max, pad_frac=0.02):
    """Per-axis data extent with small padding (TriST w axes may differ strongly, e.g. 0–40 vs 0–5)."""
    x_min, x_max = float(x_min), float(x_max)
    y_min, y_max = float(y_min), float(y_max)

    def _pad(lo, hi):
        span = hi - lo
        p = pad_frac * span if span > 0 else 0.05
        return lo - p, hi + p

    px0, px1 = _pad(x_min, x_max)
    py0, py1 = _pad(y_min, y_max)
    if x_min >= 0.0:
        px0 = max(0.0, px0)
    if y_min >= 0.0:
        py0 = max(0.0, py0)
    return px0, px1, py0, py1


def _extp_trist_plotly_scene_config(a_col, b_col, px0, px1, py0, py1, z0=None, z1=None):
    """
    Plotly 3D scene with square composition viewport and capped T-axis height.
    aspectmode='data' over-stretches T when w-axis spans differ strongly (e.g. 0–40 vs 0–5).
    """
    xspan = max(float(px1) - float(px0), 1e-9)
    yspan = max(float(py1) - float(py0), 1e-9)
    ref = max(xspan, yspan)
    if z0 is not None and z1 is not None and float(z1) > float(z0):
        zspan = float(z1) - float(z0)
    else:
        zspan = ref
    z_ratio = zspan / ref
    z_ratio = min(max(z_ratio, 0.35), 1.0)
    scene = dict(
        xaxis_title=format_chemistry_axis_label(a_col),
        yaxis_title=format_chemistry_axis_label(b_col),
        zaxis_title="T (K)",
        xaxis=dict(range=[px0, px1]),
        yaxis=dict(range=[py0, py1]),
        aspectmode="manual",
        aspectratio=dict(x=1.0, y=1.0, z=z_ratio),
    )
    if z0 is not None and z1 is not None and float(z1) > float(z0):
        scene["zaxis"] = dict(range=[float(z0), float(z1)])
    return scene


def _extp_trist_try_load_cube(xlsx_path, a_col, b_col):
    """Load companion _trist_cube.npz if axes match the selected w columns."""
    npz_p = os.path.splitext(xlsx_path)[0] + "_trist_cube.npz"
    if not os.path.isfile(npz_p):
        return None
    try:
        dnp = np.load(npz_p, allow_pickle=False)
        raw_x = dnp.get("x_col", None)
        raw_y = dnp.get("y_col", None)
        x_saved = (
            raw_x.decode("utf-8") if isinstance(raw_x, (bytes, bytearray)) else str(np.asarray(raw_x).item())
        )
        y_saved = (
            raw_y.decode("utf-8") if isinstance(raw_y, (bytes, bytearray)) else str(np.asarray(raw_y).item())
        )
        if a_col.strip() != str(x_saved).strip() or b_col.strip() != str(y_saved).strip():
            return None
        T_c = np.asarray(dnp["T_vals"], dtype=np.float64)
        xg = np.asarray(dnp["x_lin"], dtype=np.float64)
        yg = np.asarray(dnp["y_lin"], dtype=np.float64)
        f_c = np.asarray(dnp["f_cube"], dtype=np.float64)
        return T_c, yg, xg, f_c
    except Exception:
        return None


def _extp_trist_resample_ring(x, y, n):
    """Resample a closed/open polyline to n points by arc length."""
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    ok = np.isfinite(x) & np.isfinite(y)
    x, y = x[ok], y[ok]
    if len(x) < 3:
        return None, None
    span = max(float(np.ptp(x)), float(np.ptp(y)), 1.0e-9)
    if np.hypot(x[0] - x[-1], y[0] - y[-1]) > 1.0e-6 * span:
        x = np.r_[x, x[0]]
        y = np.r_[y, y[0]]
    seg = np.sqrt(np.diff(x) ** 2 + np.diff(y) ** 2)
    s = np.r_[0.0, np.cumsum(seg)]
    if s[-1] <= 0.0:
        return None, None
    su = np.linspace(0.0, s[-1], int(n), endpoint=False)
    return np.interp(su, s, x), np.interp(su, s, y)


def _extp_trist_collect_rings_per_T(dfp, a_col, b_col, n_arc=56):
    """One resampled boundary ring per temperature (largest perimeter if multiple curves)."""
    rings_by_t = {}
    dfp = dfp.copy()
    dfp["T (K)"] = pd.to_numeric(dfp["T (K)"], errors="coerce")
    grp_keys = ["T (K)", "curve_id"] if "curve_id" in dfp.columns else ["T (K)"]
    for _, gdf in dfp.dropna(subset=["T (K)", a_col, b_col]).groupby(grp_keys, sort=True):
        tval = float(gdf["T (K)"].iloc[0])
        gdf = gdf.sort_values("point_i") if "point_i" in gdf.columns else gdf
        xr = pd.to_numeric(gdf[a_col], errors="coerce").to_numpy(dtype=np.float64)
        yr = pd.to_numeric(gdf[b_col], errors="coerce").to_numpy(dtype=np.float64)
        xu, yu = _extp_trist_resample_ring(xr, yr, n_arc)
        if xu is None:
            continue
        perim = float(np.sum(np.sqrt(np.diff(xu) ** 2 + np.diff(yu) ** 2)))
        prev = rings_by_t.get(tval)
        if prev is None or perim > prev[0]:
            rings_by_t[tval] = (perim, xu, yu)
    return [(tval, rings_by_t[tval][1], rings_by_t[tval][2]) for tval in sorted(rings_by_t)]


def _extp_trist_loft_surface_mpl(ax, rings, color="#c0392b", alpha=0.48, label=None,
                                  px0=None, px1=None, py0=None, py1=None, tmin=None, tmax=None):
    """Loft resampled boundary rings into one continuous dome-like surface (Matplotlib)."""
    if not rings or len(rings) < 2:
        return False
    verts_x, verts_y, verts_z, tris = [], [], [], []

    def _add_v(xv, yv, zv):
        verts_x.append(float(xv))
        verts_y.append(float(yv))
        verts_z.append(float(zv))
        return len(verts_x) - 1

    for i in range(len(rings) - 1):
        t0, x0, y0 = rings[i]
        t1, x1, y1 = rings[i + 1]
        n = len(x0)
        for j in range(n):
            j1 = (j + 1) % n
            a = _add_v(x0[j], y0[j], t0)
            b = _add_v(x0[j1], y0[j1], t0)
            c = _add_v(x1[j], y1[j], t1)
            d = _add_v(x1[j1], y1[j1], t1)
            tris.append([a, c, b])
            tris.append([b, c, d])
    if not tris:
        return False
    vx = np.asarray(verts_x, dtype=np.float64)
    vy = np.asarray(verts_y, dtype=np.float64)
    vz = np.asarray(verts_z, dtype=np.float64)
    tri_arr = np.asarray(tris, dtype=np.int32)
    if px0 is not None and px1 is not None and py0 is not None and py1 is not None:
        tri_arr = _extp_trist_clip_mesh_faces(vx, vy, vz, tri_arr, px0, px1, py0, py1, tmin, tmax)
    if tri_arr.size == 0:
        return False
    try:
        ax.plot_trisurf(
            vx, vy, vz, triangles=tri_arr, color=color, alpha=alpha,
            linewidth=0, shade=True, antialiased=True, label=label,
        )
        return True
    except Exception:
        return False


def _extp_trist_loft_surface_plotly(tr, rings, color="rgba(192,57,43,0.55)",
                                    px0=None, px1=None, py0=None, py1=None, tmin=None, tmax=None):
    """Loft resampled boundary rings into one Plotly Mesh3d dome."""
    if not PLOTLY_AVAILABLE or not rings or len(rings) < 2:
        return None
    xs, ys, zs, tris = [], [], [], []

    def _add_v(xv, yv, zv):
        xs.append(float(xv))
        ys.append(float(yv))
        zs.append(float(zv))
        return len(xs) - 1

    for i in range(len(rings) - 1):
        t0, x0, y0 = rings[i]
        t1, x1, y1 = rings[i + 1]
        n = len(x0)
        for j in range(n):
            j1 = (j + 1) % n
            a = _add_v(x0[j], y0[j], t0)
            b = _add_v(x0[j1], y0[j1], t0)
            c = _add_v(x1[j], y1[j], t1)
            d = _add_v(x1[j1], y1[j1], t1)
            tris.extend([a, c, b, b, c, d])
    if not tris:
        return None
    xs_arr = np.asarray(xs, dtype=np.float64)
    ys_arr = np.asarray(ys, dtype=np.float64)
    zs_arr = np.asarray(zs, dtype=np.float64)
    tri_arr = np.asarray(tris, dtype=np.int32).reshape(-1, 3)
    if px0 is not None and px1 is not None and py0 is not None and py1 is not None:
        tri_arr = _extp_trist_clip_mesh_faces(xs_arr, ys_arr, zs_arr, tri_arr, px0, px1, py0, py1, tmin, tmax)
    if tri_arr.size == 0:
        return None
    return go.Mesh3d(
        x=xs_arr,
        y=ys_arr,
        z=zs_arr,
        i=tri_arr[:, 0],
        j=tri_arr[:, 1],
        k=tri_arr[:, 2],
        color=color,
        opacity=0.55,
        flatshading=False,
        name=tr("extp_trist_legend_mask_dome", "TriST region (continuous dome, f=0 surface)"),
        showscale=False,
    )


def _extp_trist_mpl_isosurface_f_zero(ax, T_vals, y_lin, x_lin, f_cube, color="#c0392b", alpha=0.48,
                                      label=None, px0=None, px1=None, py0=None, py1=None, tmin=None, tmax=None):
    """Matplotlib 3D f=0 isosurface (requires scikit-image marching_cubes)."""
    if not MATPLOTLIB_AVAILABLE:
        return False
    if px0 is not None and px1 is not None and py0 is not None and py1 is not None:
        clipped = _extp_trist_clip_cube(T_vals, y_lin, x_lin, f_cube, px0, px1, py0, py1, tmin, tmax)
        if clipped is None:
            return False
        T_vals, y_lin, x_lin, f_cube = clipped
    dense = _extp_trist_dense_f_volume(T_vals, y_lin, x_lin, f_cube)
    if dense is None:
        return False
    Tq, y_lin, x_lin, Vt, _ = dense
    try:
        from skimage.measure import marching_cubes
    except ImportError:
        return False
    try:
        nt, ny, nx = Vt.shape
        dt = float(Tq[-1] - Tq[0]) / max(nt - 1, 1)
        dy = float(y_lin[-1] - y_lin[0]) / max(ny - 1, 1) if ny > 1 else 1.0
        dx = float(x_lin[-1] - x_lin[0]) / max(nx - 1, 1) if nx > 1 else 1.0
        Vmc = np.asarray(Vt, dtype=np.float64)
        Vmc[~np.isfinite(Vmc)] = 1.0e9
        Vmc[Vmc > 0.0] = 1.0e9
        if not np.any(Vmc <= 0.0):
            return False
        verts, faces, _, _ = marching_cubes(Vmc, level=0.0, spacing=(dt, dy, dx))
        xs = verts[:, 2] * dx + float(x_lin[0])
        ys = verts[:, 1] * dy + float(y_lin[0])
        zs = verts[:, 0] * dt + float(Tq[0])
        if px0 is not None and px1 is not None and py0 is not None and py1 is not None:
            faces = _extp_trist_clip_mesh_faces(xs, ys, zs, faces, px0, px1, py0, py1, tmin, tmax)
        if faces.size == 0:
            return False
        ax.plot_trisurf(
            xs, ys, zs, triangles=faces, color=color, alpha=alpha, linewidth=0,
            shade=True, antialiased=True, label=label,
        )
        return True
    except Exception:
        return False


def _extp_trist_isosurface_f_zero(tr, T_vals, y_lin, x_lin, f_cube, opacity=0.32,
                                  px0=None, px1=None, py0=None, py1=None, tmin=None, tmax=None):
    """
    Plotly go.Isosurface for f=0, with cubic/linear regular-grid interpolation in (T, y, x).
    Scene axes: x = composition X, y = composition Y, z = T (K).
    """
    if not PLOTLY_AVAILABLE:
        return None
    if px0 is not None and px1 is not None and py0 is not None and py1 is not None:
        clipped = _extp_trist_clip_cube(T_vals, y_lin, x_lin, f_cube, px0, px1, py0, py1, tmin, tmax)
        if clipped is None:
            return None
        T_vals, y_lin, x_lin, f_cube = clipped
    dense = _extp_trist_dense_f_volume(T_vals, y_lin, x_lin, f_cube)
    if dense is None:
        return None
    Tq, y_lin, x_lin, _, V_plot = dense
    V_iso = np.asarray(V_plot, dtype=np.float64).copy()
    V_iso[~np.isfinite(V_iso)] = np.nan
    V_iso[V_iso > 0.0] = np.nan
    f_neg = V_iso[np.isfinite(V_iso)]
    if f_neg.size == 0:
        return None
    # Plotly Isosurface filters by [isomin, isomax] in physical units (J/mol), not ±1e-6.
    iso_min = float(np.min(f_neg))
    iso_max = 0.0
    name = tr(
        "extp_trist_trace_smooth",
        "TriST boundary f=0 (cubic in T, x, y; from saved 3D field)",
    )
    return go.Isosurface(
        x=x_lin,
        y=y_lin,
        z=Tq,
        value=V_iso,
        isomin=iso_min,
        isomax=iso_max,
        surface_count=1,
        showscale=False,
        opacity=opacity,
        name=name,
        caps=dict(x_show=False, y_show=False, z_show=False),
        colorscale=[[0, "rgb(255,120,80)"], [1, "rgb(180,20,20)"]],
    )


def _extp_trist_plotly_mask_dome(tr, T_vals, y_lin, x_lin, f_cube, show_volume=True,
                                 px0=None, px1=None, py0=None, py1=None, tmin=None, tmax=None):
    """Plotly traces: semi-transparent interior volume + f=0 dome surface."""
    if not PLOTLY_AVAILABLE:
        return []
    if px0 is not None and px1 is not None and py0 is not None and py1 is not None:
        clipped = _extp_trist_clip_cube(T_vals, y_lin, x_lin, f_cube, px0, px1, py0, py1, tmin, tmax)
        if clipped is None:
            return []
        T_vals, y_lin, x_lin, f_cube = clipped
    dense = _extp_trist_dense_f_volume(T_vals, y_lin, x_lin, f_cube)
    if dense is None:
        return []
    Tq, y_lin, x_lin, _, V_plot = dense
    V_vol = _extp_trist_f_for_viz_volume(V_plot)
    traces = []
    if show_volume:
        f_neg = V_vol[np.isfinite(V_vol)]
        if f_neg.size:
            traces.append(
                go.Volume(
                    x=x_lin,
                    y=y_lin,
                    z=Tq,
                    value=V_vol,
                    isomin=float(np.nanmin(f_neg)),
                    isomax=min(-1.0e-8, float(np.nanmax(f_neg))),
                    opacity=0.16,
                    surface_count=8,
                    colorscale=[[0, "rgb(255,230,230)"], [1, "rgb(200,40,40)"]],
                    showscale=False,
                    name=tr("extp_trist_legend_mask_vol", "TriST inside (volume)"),
                    caps=dict(x_show=False, y_show=False, z_show=False),
                )
            )
    iso = _extp_trist_isosurface_f_zero(
        tr, T_vals, y_lin, x_lin, f_cube, opacity=0.58,
    )
    if iso is not None:
        iso.name = tr("extp_trist_legend_mask_dome", "TriST region (continuous dome, f=0 surface)")
        traces.append(iso)
    return traces


