        ttk.Entry(g_add_fr, textvariable=g_min, width=10).pack(side=tk.LEFT, padx=5)
        g_lbl_max = ttk.Label(g_add_fr, text=self.tr('tbatch_lbl_max', 'Max:'))
        g_lbl_max.pack(side=tk.LEFT, padx=5)
