        target_temp_var2 = tk.StringVar()
        tab2_lbl_target_temp = ttk.Label(
            tab2_temp_frame, text=self.tr('stp_target_temp', 'Target Temperature (K):')
        )
        tab2_lbl_target_temp.pack(side=tk.LEFT, padx=5)
